// Company books, real journal workflow and posted-only reports. No business data is embedded.
const accLabels={draft:['草稿','Draft','សេចក្តីព្រាង'],returned:['退回修改','Returned','ត្រឡប់ឱ្យកែ'],withdrawn:['已撤回','Withdrawn','បានដកសំណើ'],in_review:['待複核','In review','រង់ចាំពិនិត្យ'],in_approval:['待核准','In approval','រង់ចាំអនុម័ត'],approved:['已核准，待入帳','Approved, not posted','អនុម័ត រង់ចាំកត់ត្រា'],posted:['已入帳','Posted','បានកត់ត្រា'],void:['已作廢','Void','មោឃៈ']};
const accActionLabels={create:['建立草稿','Create draft','បង្កើតសេចក្តីព្រាង'],before_edit:['修改前紀錄','Before revision','មុនកែប្រែ'],save:['儲存修改','Save changes','រក្សាការកែ'],reversed:['已由沖回傳票更正','Reversed by linked voucher','កែដោយប័ណ្ណត្រឡប់'],edit:['編輯傳票','Edit voucher','កែប័ណ្ណ'],submit:['送複核','Submit for review','ផ្ញើពិនិត្យ'],review:['完成複核','Complete review','បញ្ចប់ពិនិត្យ'],approve:['核准','Approve','អនុម័ត'],revise:['複核修改','Revise during review','កែពេលពិនិត្យ'],return:['退回修改','Return','ត្រឡប់ឱ្យកែ'],withdraw:['撤回','Withdraw','ដកសំណើ'],post:['正式入帳','Post to ledger','កត់ត្រាចូលបញ្ជី'],reverse:['建立沖回傳票','Prepare reversal','បង្កើតប័ណ្ណត្រឡប់'],void:['作廢草稿','Void draft','លុបសេចក្តីព្រាង']};
const accTypeLabels={asset:['資產','Assets','ទ្រព្យសកម្ម'],liability:['負債','Liabilities','បំណុល'],equity:['權益','Equity','មូលធន'],revenue:['收入','Revenue','ចំណូល'],expense:['費用','Expenses','ចំណាយ']};
let accountingReportCache=null,accountingWorkbookImport=null,accountingOpeningPreview=null;
const accS=()=>state.accounting||{companies:[],books:[],accounts:[],entries:[],sources:[],reports:[],templates:[],capabilities:{},routeCandidates:[]};
const accCompany=()=>{const c=route().company||state.company;return accS().companies.includes(c)?c:accS().companies.length===1?accS().companies[0]:''};
const accBook=c=>accS().books.find(b=>b.company===c);
const accCap=(c,a)=>!!accS().capabilities?.[c]?.[a];
const accText=(a)=>L(...a);
const accAmount=(n,book)=>n===undefined?'—':(n/10**(book?.precision??2)).toLocaleString(lang==='zh'?'zh-Hant':lang==='km'?'km':'en',{minimumFractionDigits:book?.precision??2,maximumFractionDigits:book?.precision??2});
const accDecimal=(n,p)=>{let v=String(Math.abs(n||0)).padStart(p+1,'0');return (n<0?'-':'')+(p?v.slice(0,-p)+'.'+v.slice(-p):v)};
const accInput=(label,name,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" value="${esc(value)}" type="${type}" ${attrs}></label>`;
const accNote=(label,name,value='',required=true)=>`<label>${esc(label)}<textarea name="${name}" maxlength="1000" ${required?'required':''}>${esc(value)}</textarea></label>`;
const accSubmit=(label)=>`<div class="error" role="alert"></div><div class="button-row"><button class="primary" type="submit">${esc(label)}</button><button type="button" data-action="close">${t('取消')}</button></div>`;
const accTabs=()=>`<nav class="tabs" aria-label="${L('財務功能','Finance functions','មុខងារហិរញ្ញវត្ថុ')}">${[['journals',['傳票與入帳','Vouchers & posting','ប័ណ្ណ និងការកត់ត្រា']],['accounts',['科目與試算','Accounts & trial','គណនី និងតុល្យភាព']],['reports',['財務報表','Financial reports','របាយការណ៍ហិរញ្ញវត្ថុ']],['opening',['前期／期初餘額','Prior / opening balances','សមតុល្យមុន / ដើម']],['imports',['匯入／匯出','Import / export','នាំចូល / នាំចេញ']],['book',['帳套與簽核','Book & approvals','បញ្ជី និងការអនុម័ត']],['receivable',['收付款申請','Financial requests','សំណើហិរញ្ញវត្ថុ']]].map(([key,name])=>`<a class="${(route().tab||'journals')===key?'active':''}" href="${href('finance',{tab:key,...(accCompany()?{company:accCompany()}:{})})}">${accText(name)}</a>`).join('')}</nav>`;
const accStyles='';
// The current voucher turn comes from its submitted route, never from guessed role assignments.
function accSelectorLabel(selector,company,type='review'){
 const stage=type==='review'?L('複核','Review','ពិនិត្យ'):L('核准','Approval','អនុម័ត');
 if(selector?.startsWith('user:')){const person=accS().routeCandidates.find(p=>p.id===selector.slice(5)&&p.companies?.includes(company));return person?.name||L(`指定${stage}帳號`,`Assigned ${stage.toLowerCase()} account`,`គណនីដែលបានកំណត់សម្រាប់${stage}`)}
 if(selector?.startsWith('position:'))return state.positions?.positions?.find(p=>p.id===selector.slice(9)&&p.company===company)?.name||L(`指定${stage}職位`,`Assigned ${stage.toLowerCase()} position`,`តួនាទីដែលបានកំណត់សម្រាប់${stage}`);
 return ({finance:L('財務角色','Finance role','តួនាទីហិរញ្ញវត្ថុ'),executive:L('經營主管角色','Executive role','តួនាទីថ្នាក់ដឹកនាំ'),manager:L('公司主管角色','Company manager role','តួនាទីអ្នកគ្រប់គ្រងក្រុមហ៊ុន'),owner:L('管理員角色','Administrator role','តួនាទីអ្នកគ្រប់គ្រងប្រព័ន្ធ')})[selector]||L(`指定${stage}關卡`,`Configured ${stage.toLowerCase()} stage`,`ដំណាក់កាល${stage}ដែលបានកំណត់`);
}
function accEntryTurn(r,book){
 const actions=r.actions||[],stage=r.route?.stages?.[r.step],nextStage=r.route?.stages?.[r.step+1],creator=r.history?.find(h=>h.action==='create'&&h.actor===r.createdBy)?.actorName||(state.session?.user.id===r.createdBy?state.session.user.display_name:'')||L('傳票建立人','Voucher preparer','អ្នករៀបចំប័ណ្ណ');
 if(['draft','returned','withdrawn'].includes(r.status))return {who:creator,next:r.status==='returned'?L('修改退回內容，再送複核。','Revise the returned items, then submit for review.','កែចំណុចដែលត្រឡប់ រួចផ្ញើពិនិត្យ។'):L('核對日期、科目與金額後送複核。','Check the date, accounts and amounts, then submit for review.','ពិនិត្យកាលបរិច្ឆេទ គណនី និងចំនួន រួចផ្ញើពិនិត្យ។'),action:actions.includes('edit')?'edit':actions.includes('submit')?'submit':null};
 if(['in_review','in_approval'].includes(r.status)){
  const type=r.status==='in_review'?'review':'approve',label=type==='review'?L('複核','Review','ពិនិត្យ'):L('核准','Approval','អនុម័ត'),who=stage?accSelectorLabel(stage.selector,r.company,type):L('待核對簽核設定','Approval setup needs checking','ត្រូវពិនិត្យការកំណត់អនុម័ត');
  return {who:`${label} · ${who}`,next:nextStage?L(`完成後交 ${accSelectorLabel(nextStage.selector,r.company,nextStage.type)} 核准。`,`Then send to ${accSelectorLabel(nextStage.selector,r.company,nextStage.type)} for approval.`,`បន្ទាប់មកផ្ញើទៅ ${accSelectorLabel(nextStage.selector,r.company,nextStage.type)} ដើម្បីអនុម័ត។`):L('本關完成後，交具入帳權限的人員正式入帳。','After this stage, an authorized posting operator posts the voucher.','ក្រោយដំណាក់កាលនេះ អ្នកមានសិទ្ធិកត់ត្រាប័ណ្ណចូលបញ្ជី។'),action:actions.includes(type)?type:null};
 }
 if(r.status==='approved')return {who:L('具入帳權限的人員','Authorized posting operator','អ្នកមានសិទ្ធិកត់ត្រាចូលបញ្ជី'),next:L('正式入帳後才納入報表；不會自動付款。','Posting includes it in reports; it does not make a payment.','កត់ត្រារួចទើបបញ្ចូលក្នុងរបាយការណ៍ មិនទូទាត់ដោយស្វ័យប្រវត្តិ។'),action:actions.includes('post')?'post':null};
 if(r.status==='posted')return {who:L('已完成入帳','Posting completed','បានកត់ត្រាចូលបញ្ជី'),next:r.reversedBy?L('已由關聯沖回傳票更正，原紀錄保留。','Corrected by the linked reversal; the original is retained.','កែដោយប័ណ្ណត្រឡប់ ហើយរក្សាកំណត់ត្រាដើម។'):L('已納入報表；如需更正，另建沖回傳票。','Included in reports; create a reversal if correction is needed.','បានបញ្ចូលក្នុងរបាយការណ៍។ បើត្រូវកែ សូមបង្កើតប័ណ្ណត្រឡប់។'),action:null};
 return {who:L('已結束','Closed','បានបញ្ចប់'),next:L('保留原紀錄，不會入帳或付款。','Retained for reference; no posting or payment.','រក្សាកំណត់ត្រា មិនកត់ត្រាចូលបញ្ជី ឬទូទាត់។'),action:null};
}
function accEntryContext(r,book,inline=false){const turn=accEntryTurn(r,book);return `<${inline?'div':'section'} class="${inline?'flow-inline':'flow-context'} ${turn.action?'flow-context-action':'flow-context-wait'}"><small class="flow-context-label">${L('目前處理','Current turn','អ្នកដោះស្រាយបច្ចុប្បន្ន')}</small><strong>${esc(turn.who)}</strong><p class="flow-context-next">${esc(turn.next)}</p>${!inline&&turn.action?`<small>${L('輪到你處理，可使用下方按鈕。','Your action is available below.','អ្នកអាចប្រើប៊ូតុងខាងក្រោមដើម្បីដោះស្រាយ។')}</small>`:''}</${inline?'div':'section'}>`}
function accEntryMobileList(entries,book){return `<div class="wf-mobile-list">${entries.length?entries.map(r=>`<article class="card"><span class="badge ${r.status==='posted'?'green':'amber'}">${accText(accLabels[r.status])}</span><h3>${esc(r.description)}</h3><p class="sub">${esc(r.number||r.id)} · ${esc(r.date)}</p><p><strong>${accAmount(r.lines.reduce((n,l)=>n+l.debit,0),book)} ${esc(r.currency)}</strong></p>${accEntryContext(r,book,true)}<div class="button-row">${accEntryListAction(r,book)}</div></article>`).join(''):`<p class="card sub">${L('尚無傳票','No vouchers yet','មិនទាន់មានប័ណ្ណ')}</p>`}</div>`}
function accEntryListAction(r,book){
 const action=accEntryTurn(r,book).action,url=href('finance',{tab:'journals',company:r.company,detail:r.id});
 if(['review','approve','post'].includes(action)){const labels={review:['開啟並複核','Open for review','បើកដើម្បីពិនិត្យ'],approve:['開啟並核准','Open for approval','បើកដើម្បីអនុម័ត'],post:['開啟並入帳','Open for posting','បើកដើម្បីកត់ត្រា']};return `<a class="button primary" href="${url}">${accText(labels[action])}</a>`}
 return `${action?button(accText(accActionLabels[action]),action==='edit'?'acc-entry':'acc-act',`data-id="${esc(r.id)}" data-kind="${action}"`,true):''}<a href="${url}">${t('查看')} →</a>`;
}

function renderAccounting(){
 const c=accCompany(),book=accBook(c),tab=route().tab||'journals',head=accStyles+title(L('財務與會計','Finance & accounting','ហិរញ្ញវត្ថុ និងគណនេយ្យ'),L('先選公司；輸入、複核、核准完成後，再正式入帳。','Select a company. Prepare, review and approve before posting.','ជ្រើសក្រុមហ៊ុន រៀបចំ ពិនិត្យ អនុម័ត រួចកត់ត្រា។'))+accTabs();
 if(!c)return head+`<div class="grid">${accS().companies.map(x=>`<section class="card"><h2>${esc(companyName(x))}</h2><p>${accBook(x)?esc(accBook(x).currency):L('帳套待確認','Book not configured','មិនទាន់កំណត់បញ្ជី')}</p><a href="${href('finance',{tab,company:x})}">${L('進入這家公司 →','Open this company →','ចូលក្រុមហ៊ុននេះ →')}</a></section>`).join('')||empty(L('沒有帳務權限','No accounting access','គ្មានសិទ្ធិគណនេយ្យ'))}</div>`;
 const companyLine=`<p><span class="badge">${esc(companyName(c))}</span> ${book?esc(book.currency)+' · '+L('小數','Decimals','ខ្ទង់ទសភាគ')+' '+book.precision:''}</p>`;
 if(!book?.enabled&&!['book','imports','accounts'].includes(tab))return head+companyLine+accTemplateCard(c)+`<section class="card"><h2>${L('先確認這家公司的帳套','Confirm this company’s book first','បញ្ជាក់បញ្ជីក្រុមហ៊ុននេះជាមុន')}</h2><p>${L('需要財務確認幣別、起始日、科目表與簽核職位。沒有預填金額或替公司指派人員。','Finance must confirm currency, start date, accounts and approval roles. No balances or assignments are prefilled.','ត្រូវបញ្ជាក់រូបិយប័ណ្ណ ថ្ងៃចាប់ផ្តើម គណនី និងអ្នកអនុម័ត។ មិនបំពេញសមតុល្យឬបុគ្គលិកជាមុនទេ។')}</p>${accCap(c,'configure')?button(L('設定帳套與簽核','Configure book & approvals','កំណត់បញ្ជី និងអនុម័ត'),'acc-setup',`data-company="${esc(c)}"`):''}</section>`;
 if(tab==='book')return head+companyLine+accTemplateCard(c)+accBookView(c,book);
 if(tab==='accounts')return head+companyLine+accTemplateCard(c)+accAccountsView(c,book);
 if(tab==='reports')return head+companyLine+accReportView(c,book);
 if(tab==='imports')return head+companyLine+accTemplateCard(c)+accImportsView(c,book);
 if(tab==='opening')return head+companyLine+accOpeningView(c,book);
 const r=accS().entries.find(e=>e.id===route().detail&&e.company===c);if(r)return head+companyLine+accEntryView(r,book);
 const entries=accS().entries.filter(e=>e.company===c).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return head+companyLine+`<div class="acc-flow"><span>${L('① 填寫傳票','① Prepare','① រៀបចំ')}</span><span>${L('② 複核／修改','② Review / revise','② ពិនិត្យ / កែ')}</span><span>${L('③ 核准','③ Approve','③ អនុម័ត')}</span><span>${L('④ 入帳、產生報表','④ Post → reports','④ កត់ត្រា → របាយការណ៍')}</span></div><div class="toolbar">${accCap(c,'create')?button(L('新增傳票','New voucher','បន្ថែមប័ណ្ណ'),'acc-entry',`data-company="${esc(c)}"`):''}<span class="count">${entries.length} ${t('筆資料')}</span></div>`+`<div class="workflow-list">`+table([L('傳票／摘要','Voucher / description','ប័ណ្ណ / សេចក្តីសង្ខេប'),L('日期','Date','កាលបរិច្ឆេទ'),'金額','狀態',''],entries.map(e=>`<tr><td><strong>${esc(e.number||e.id)}</strong><small>${esc(e.description)}</small>${e.kind==='opening'?`<span class="badge">${L('期初餘額','Opening balance','សមតុល្យដើម')}</span>`:''}${e.reversalOf?`<span class="badge">${L('沖回','Reversal','ត្រឡប់')}</span>`:''}</td><td>${esc(e.date)}</td><td>${accAmount(e.lines.reduce((n,l)=>n+l.debit,0),book)}</td><td><span class="badge ${e.status==='posted'?'green':'amber'}">${accText(accLabels[e.status])}</span>${accEntryContext(e,book,true)}</td><td>${accEntryListAction(e,book)}</td></tr>`))+accEntryMobileList(entries,book)+`</div>`+
 `<p class="footnote">${L('只有已入帳傳票會進入報表；核准不代表已付款。已入帳資料以沖回傳票更正，保留原紀錄。','Only posted vouchers appear in reports. Approval is not payment. Correct posted entries with a linked reversal.','របាយការណ៍ប្រើតែប័ណ្ណបានកត់ត្រា។ អនុម័តមិនមែនទូទាត់។ កែដោយប័ណ្ណត្រឡប់ និងរក្សាដើម។')}</p>`;
}
function accBookView(c,book){const selectorName=key=>key.startsWith('user:')?accS().routeCandidates.find(a=>a.id===key.slice(5))?.name||key:key.startsWith('position:')?state.positions?.positions.find(p=>p.id===key.slice(9))?.name||key:roleName(key);return `<section class="card acc-book"><h2>${L('帳套與作業規則','Book and operating rules','បញ្ជី និងច្បាប់ការងារ')}</h2>${book?`<dl class="details"><div><dt>${L('起始日','Opening date','ថ្ងៃចាប់ផ្តើម')}</dt><dd>${esc(book.openingDate)}</dd></div><div><dt>${L('已結帳至','Closed through','បិទដល់')}</dt><dd>${esc(book.closedThrough||'—')}</dd></div><div><dt>${t('狀態')}</dt><dd>${book.enabled?t('啟用'):t('已停用')}</dd></div></dl><ol>${book.stages.map(s=>`<li>${s.type==='review'?L('複核','Review','ពិនិត្យ'):L('核准','Approve','អនុម័ត')}：${esc(selectorName(s.selector))}</li>`).join('')}</ol>`:`<p>${L('尚未設定，不會自動指定人員或幣別。','Not configured. No people or currency are assigned automatically.','មិនទាន់កំណត់។ មិនចាត់តាំងមនុស្សឬរូបិយប័ណ្ណដោយស្វ័យប្រវត្តិ។')}</p>`}${accCap(c,'configure')?`<div class="button-row">${button(L('設定帳套與簽核','Configure book & approvals','កំណត់បញ្ជី និងអនុម័ត'),'acc-setup',`data-company="${esc(c)}"`)}${book?.enabled?button(L('鎖定已結帳期間','Close accounting period','បិទរយៈពេលគណនេយ្យ'),'acc-close',`data-company="${esc(c)}"`,false):''}</div>`:''}</section><section class="card section-gap"><h2>${L('待財務確認的細則','Finance decisions still needed','ចំណុចហិរញ្ញវត្ថុត្រូវបញ្ជាក់')}</h2><ul><li>${L('正式科目表、期初餘額與報表格式。','Official chart, opening balances and report layouts.','បញ្ជីគណនី សមតុល្យដើម និងទម្រង់របាយការណ៍។')}</li><li>${L('實際複核、核准、入帳人員與金額門檻。','Actual reviewers, approvers, posting operators and amount thresholds.','អ្នកពិនិត្យ អ្នកអនុម័ត អ្នកកត់ត្រា និងកម្រិតទឹកប្រាក់។')}</li><li>${L('外幣換算、稅務、薪資計算及 PMS 正式串接規格。','Foreign exchange, tax, payroll calculation and the PMS integration contract.','ប្តូររូបិយប័ណ្ណ ពន្ធ គណនាប្រាក់ខែ និងការតភ្ជាប់ PMS។')}</li></ul><p class="sub">${L('這些規則尚未自動計算；目前帳套採一家公司一個明確的記帳幣別。','These rules are not calculated automatically. Each company uses one explicitly configured book currency.','ច្បាប់ទាំងនេះមិនគណនាដោយស្វ័យប្រវត្តិ។ ក្រុមហ៊ុននីមួយៗប្រើរូបិយប័ណ្ណបញ្ជីដែលបានកំណត់។')}</p></section>`}
function accAccountsView(c,book){const actual=accS().accounts.filter(a=>a.company===c),rows=(actual.length?actual:accTemplate(c)?.accounts||[]).slice().sort((a,b)=>a.code.localeCompare(b.code));return `<div class="toolbar">${accCap(c,'configure')&&book?.enabled?button(L('新增科目','New account','បន្ថែមគណនី'),'acc-account',`data-company="${esc(c)}"`):''}</div><label class="acc-table-search">${L('搜尋代碼或名稱','Find code or name','ស្វែងរកលេខ ឬឈ្មោះ')}<input type="search" data-acc-search placeholder="${L('輸入代碼開頭或科目名稱','Enter code prefix or account name','បញ្ចូលលេខដើម ឬឈ្មោះគណនី')}"></label>`+table([L('代碼','Code','លេខកូដ'),L('科目名稱','Account name','ឈ្មោះគណនី'),L('分類／性質','Type / normal balance','ប្រភេទ / សមតុល្យ'),L('上層科目','Parent account','គណនីមេ'),'狀態',''],rows.map(a=>`<tr data-acc-row data-search="${esc((a.code+' '+a.name+' '+(a.nameZh||'')).toLowerCase())}"><td>${esc(a.code)}</td><td><strong>${esc(accName(a))}</strong>${a.nameZh&&lang!=='zh'?`<small>${esc(a.nameZh)}</small>`:''}<small>${a.posting!==false?L('可入帳明細','Posting account','គណនីកត់ត្រា'):L('彙總科目','Group account','គណនីក្រុម')}</small></td><td>${accText(accTypeLabels[a.type])} · ${a.normal==='debit'?L('借','Debit','ឥណពន្ធ'):L('貸','Credit','ឥណទាន')}</td><td>${esc(a.parentCode||'—')}</td><td>${!a.id?L('範本','Template','គំរូ'):a.enabled?t('啟用'):t('已停用')}</td><td>${accCap(c,'configure')&&a.id?button(L('編輯','Edit','កែ'), 'acc-account',`data-id="${esc(a.id)}" data-company="${esc(c)}"`,false):''}</td></tr>`))+`<p class="footnote">${L('科目由財務建立或從 CSV 匯入。已使用的科目保留代碼與分類，停用後不可新增分錄。','Finance creates accounts or imports CSV. Used codes and classifications remain fixed; disabled accounts reject new entries.','ហិរញ្ញវត្ថុបង្កើតគណនី ឬនាំចូល CSV។ លេខ និងប្រភេទដែលប្រើរួចមិនប្តូរ; គណនីបិទមិនទទួលកំណត់ត្រាថ្មី។')}</p>`}
function accEntryView(r,book){const total=r.lines.reduce((n,l)=>n+l.debit,0),accountName=code=>accS().accounts.find(a=>a.company===r.company&&a.code===code)?.name||'';return `<div class="toolbar"><a href="${href('finance',{tab:'journals',company:r.company})}">← ${L('返回傳票清單','Back to vouchers','ត្រឡប់ទៅបញ្ជីប័ណ្ណ')}</a></div><section class="card acc-detail"><span class="badge">${accText(accLabels[r.status])}</span><h2>${esc(r.number||r.id)}</h2><p>${esc(r.description)}</p><p>${esc(r.date)} · ${esc(r.reference)} · ${esc(r.currency)}</p>${r.sourceId?`<p>${L('來源申請','Source request','សំណើប្រភព')}：${button(r.sourceId,'view-record',`data-id="${esc(r.sourceId)}"`,false)}</p>`:''}${r.reversalOf||r.reversedBy?`<p>${L('關聯沖回紀錄','Related reversal','កំណត់ត្រាត្រឡប់')}：<a href="${href('finance',{company:r.company,tab:'journals',detail:r.reversalOf||r.reversedBy})}">${esc(r.reversalOf||r.reversedBy)}</a></p>`:''}${accEntryContext(r,book)}<div class="button-row">${r.actions.map(a=>button(accText(accActionLabels[a]),a==='edit'||a==='revise'?'acc-entry':'acc-act',`data-id="${esc(r.id)}" data-kind="${a}"`,['submit','review','approve','post'].includes(a))).join('')}</div></section>`+table([L('科目','Account','គណនី'),L('摘要','Description','សេចក្តីសង្ខេប'),L('借方','Debit','ឥណពន្ធ'),L('貸方','Credit','ឥណទាន')],r.lines.map(l=>`<tr><td>${esc(l.accountCode)}<small>${esc(accountName(l.accountCode))}</small></td><td>${esc(l.description)}${accJournalDetails(l)}</td><td>${accAmount(l.debit,book)}</td><td>${accAmount(l.credit,book)}</td></tr>`))+`<p class="acc-total">${L('借貸合計','Debit / credit totals','សរុបឥណពន្ធ / ឥណទាន')}：${accAmount(total,book)} / ${accAmount(total,book)} ${esc(book.currency)}</p><section class="card"><h2>${t('操作紀錄')}</h2>${r.history.slice().reverse().map(h=>`<details><summary>${esc(h.at.replace('T',' ').slice(0,16))} · ${esc(h.actorName||h.actor)} · ${esc(accActionLabels[h.action]?accText(accActionLabels[h.action]):h.action)} · v${h.revision}</summary><p>${esc(h.reason||'—')}</p>${h.snapshot?`<p>${esc(h.snapshot.description||'')} · ${esc(h.snapshot.date||'')}</p><pre class="acc-history-lines">${esc((h.snapshot.lines||[]).map(l=>`${l.accountCode} | ${accAmount(l.debit,book)} / ${accAmount(l.credit,book)} | ${l.description||''}`).join('\n'))}</pre>`:''}</details>`).join('')}</section>`}
function accReportView(c,book){
 const r=accountingReportCache?.company===c&&accountingReportCache.revision===accS().revision?accountingReportCache.report:accS().reports.find(r=>r.company===c);if(!r)return empty(t('尚無紀錄'));
 const kind=route().report||'trial',head=`<form class="acc-toolbar" data-form="accounting" data-kind="report" data-company="${esc(c)}">${accInput(L('起始日期','From','ចាប់ពី'),'start',r.start,'date','required')}${accInput(L('截止日期','Through','រហូតដល់'),'end',r.end,'date','required')}<button class="primary" type="submit">${L('更新報表','Run report','បង្ហាញរបាយការណ៍')}</button><div class="error" role="alert"></div></form><p class="sub">${L('只包含已入帳資料','Posted entries only','តែកំណត់ត្រាបានកត់ត្រា')} · ${r.postedCount} ${L('張傳票','vouchers','ប័ណ្ណ')} · ${esc(book.currency)}</p><nav class="tabs" aria-label="${L('選擇報表','Choose report','ជ្រើសរបាយការណ៍')}">${[['trial',['試算表','Trial balance','តារាងតុល្យភាព']],['profit',['每月損益','Monthly profit & loss','ចំណេញខាតប្រចាំខែ']],['balance',['資產負債比較','Comparative balance sheet','តុល្យការប្រៀបធៀប']],['cashflow',['現金流量','Cash flow','លំហូរសាច់ប្រាក់']],['ledger',['總分類帳','General ledger','បញ្ជីធំ']]].map(([key,label])=>`<a class="${key===kind?'active':''}" href="${href('finance',{company:c,tab:'reports',report:key})}">${accText(label)}</a>`).join('')}</nav>`;
 const exportKind=kind==='profit'&&r.profitMonthly?'profitMonthly':kind==='balance'&&r.comparativeBalance?'comparativeBalance':kind;
 const exports=accCap(c,'export')?`<p>${button(L('下載此報表 CSV','Download report CSV','ទាញយករបាយការណ៍ CSV'),'acc-export',`data-company="${esc(c)}" data-kind="${exportKind}" data-start="${r.start}" data-end="${r.end}"`,false)}</p>`:'';
 if(kind==='ledger')return head+exports+table([L('日期／傳票','Date / voucher','កាលបរិច្ឆេទ / ប័ណ្ណ'),L('科目','Account','គណនី'),L('摘要','Description','សង្ខេប'),L('借方','Debit','ឥណពន្ធ'),L('貸方','Credit','ឥណទាន'),L('借方餘額','Debit balance','សមតុល្យឥណពន្ធ')],r.ledger.map(l=>`<tr><td><a href="${href('finance',{company:c,tab:'journals',detail:l.entryId})}">${esc(l.number)}</a><small>${esc(l.date)}</small></td><td>${esc(l.accountCode)}</td><td>${esc(l.description)}</td><td class="money">${accAmount(l.debit,book)}</td><td class="money">${accAmount(l.credit,book)}</td><td class="money">${accAmount(l.balance,book)}</td></tr>`));
 if(kind==='cashflow')return head+exports+accCashflowView(r,book);
 if(kind==='profit')return head+`<div class="acc-summary">${[[L('本期收入','Period revenue','ចំណូលរយៈពេល'),r.profit.revenue],[L('成本與費用','Costs & expenses','ថ្លៃ និងចំណាយ'),r.profit.expense],[L('本期損益','Period result','លទ្ធផលរយៈពេល'),r.profit.result]].map(([label,value])=>`<div class="card">${label}<strong>${accAmount(value,book)}</strong></div>`).join('')}</div>`+exports+(r.profitMonthly?accMonthlyProfit(r,book):table([L('科目','Account','គណនី'),L('分類','Type','ប្រភេទ'),L('本期金額','Period amount','ចំនួនរយៈពេល')],r.rows.filter(x=>['revenue','expense'].includes(x.type)&&x.debit+x.credit).map(x=>`<tr><td>${esc(x.code+' '+x.name)}</td><td>${accText(accTypeLabels[x.type])}</td><td class="money">${accAmount(x.type==='revenue'?x.credit-x.debit:x.debit-x.credit,book)}</td></tr>`)));
 if(kind==='balance')return head+`<div class="acc-summary">${[[L('資產','Assets','ទ្រព្យសកម្ម'),r.balance.assets],[L('負債','Liabilities','បំណុល'),r.balance.liabilities],[L('權益＋未結轉損益','Equity + unclosed result','មូលធន + លទ្ធផលមិនបិទ'),r.balance.equity+r.balance.unclosedResult]].map(([label,value])=>`<div class="card">${label}<strong>${accAmount(value,book)}</strong></div>`).join('')}</div><p>${L('未結轉損益（系統計算）','Unclosed result (calculated)','លទ្ធផលមិនបិទ (គណនា)')}：${accAmount(r.balance.unclosedResult,book)} · ${L('平衡差額','Balance difference','ភាពខុសគ្នាតុល្យការ')}：<strong>${accAmount(r.balance.difference,book)}</strong></p>`+exports+(r.comparativeBalance?accComparativeBalance(r,book):table([L('科目','Account','គណនី'),L('分類','Type','ប្រភេទ'),L('截止日餘額','Balance at end date','សមតុល្យចុងថ្ងៃ')],r.rows.filter(x=>['asset','liability','equity'].includes(x.type)&&x.net).map(x=>`<tr><td>${esc(x.code+' '+x.name)}</td><td>${accText(accTypeLabels[x.type])}</td><td class="money">${accAmount(x.type==='asset'?x.net:-x.net,book)}</td></tr>`)))+`<p class="footnote">${L('未結轉損益另外列示；期初餘額須完成入帳才會納入。','Unclosed results are shown separately. Opening balances appear only after posting.','លទ្ធផលមិនបិទបង្ហាញដោយឡែក។ សមតុល្យដើមបញ្ចូលតែក្រោយកត់ត្រា។')}</p>`;
 return head+exports+`<p>${L('借方餘額合計','Total debit balances','សរុបសមតុល្យឥណពន្ធ')} ${accAmount(r.trial.debit,book)} = ${L('貸方餘額合計','Total credit balances','សរុបសមតុល្យឥណទាន')} ${accAmount(r.trial.credit,book)}</p>`+table([L('科目','Account','គណនី'),L('期初借方餘額','Opening debit balance','សមតុល្យឥណពន្ធដើម'),L('本期借方','Period debit','ឥណពន្ធរយៈពេល'),L('本期貸方','Period credit','ឥណទានរយៈពេល'),L('期末借方餘額','Closing debit balance','សមតុល្យឥណពន្ធចុង')],r.rows.filter(x=>x.opening||x.debit||x.credit).map(x=>`<tr><td>${esc(x.code+' '+x.name)}</td><td class="money">${accAmount(x.opening,book)}</td><td class="money">${accAmount(x.debit,book)}</td><td class="money">${accAmount(x.credit,book)}</td><td class="money">${accAmount(x.net,book)}</td></tr>`))+`<p class="footnote">${L('負數表示貸方餘額。可切換總分類帳，逐筆回到原傳票。','Negative values indicate credit balances. Use the general ledger to open each source voucher.','លេខអវិជ្ជមានជាសមតុល្យឥណទាន។ ប្រើបញ្ជីធំដើម្បីបើកប័ណ្ណដើម។')}</p>`;
}
function accImportsView(c,book){return accWorkbookPanel(c,book)+(!book?.enabled?'':`<div class="grid"><section class="card"><h2>${L('傳票批次匯入','Batch voucher import','នាំចូលប័ណ្ណជាបាច់')}</h2><p>${L('Excel 另存 UTF-8 CSV → 上傳 → 預覽錯誤 → 確認匯入草稿。整批通過才會儲存，仍須複核、核准與入帳。','Save Excel as UTF-8 CSV → upload → preview → import drafts. The whole batch must pass, then follow review, approval and posting.','រក្សា Excel ជា UTF-8 CSV → ផ្ទុក → ពិនិត្យ → នាំចូលសេចក្តីព្រាង។ ត្រូវឆ្លងពិនិត្យ អនុម័ត និងកត់ត្រា។')}</p><div class="button-row">${accCap(c,'export')?button(L('下載空白 CSV 範本','Download blank CSV template','ទាញយកគំរូ CSV'),'acc-export',`data-company="${esc(c)}" data-kind="template"`,false):''}${accCap(c,'create')?button(L('匯入傳票 CSV','Import voucher CSV','នាំចូលប័ណ្ណ CSV'),'acc-import',`data-company="${esc(c)}" data-kind="journals"`):''}</div></section><section class="card"><h2>${L('科目表匯入與匯出','Chart import / export','នាំចូល / ចេញបញ្ជីគណនី')}</h2><p>${L('依上層到下層排列；代碼相同會更新名稱與啟用狀態，已使用科目的分類不可改。','Order parent accounts before children. Matching codes update names/status; used classifications remain fixed.','រៀបគណនីមេមុនកូន។ លេខដូចគ្នាធ្វើបច្ចុប្បន្នភាពឈ្មោះ/ស្ថានភាព។')}</p><div class="button-row">${accCap(c,'export')?button(L('匯出科目 CSV','Export accounts CSV','នាំចេញគណនី CSV'),'acc-export',`data-company="${esc(c)}" data-kind="accounts"`,false):''}${accCap(c,'configure')?button(L('匯入科目 CSV','Import accounts CSV','នាំចូលគណនី CSV'),'acc-import',`data-company="${esc(c)}" data-kind="accounts"`):''}</div></section><section class="card"><h2>${L('匯出已入帳資料','Export posted entries','នាំចេញកំណត់ត្រា')}</h2><p>${L('僅匯出這家公司已入帳的傳票。明細報表可在財務報表頁指定日期。','Exports posted vouchers for this company only. Choose report dates on the reports page.','នាំចេញតែប័ណ្ណក្រុមហ៊ុននេះដែលបានកត់ត្រា។ ជ្រើសថ្ងៃនៅទំព័ររបាយការណ៍។')}</p>${accCap(c,'export')?button(L('下載已入帳傳票 CSV','Download posted vouchers CSV','ទាញយកប័ណ្ណ CSV'),'acc-export',`data-company="${esc(c)}" data-kind="journals"`,false):''}</section></div>`)}
function accSetupForm(c){const book=accBook(c),options=[...(state.positions?.positions||[]).filter(p=>p.company===c&&p.enabled).map(p=>['position:'+p.id,p.name]),...accS().routeCandidates.filter(a=>a.companies.includes(c)).map(a=>['user:'+a.id,a.name+' · '+roleName(a.rolesByCompany?.[c]||a.role)])];modal(L('設定公司帳套','Configure company book','កំណត់បញ្ជីក្រុមហ៊ុន'),`<form class="form" data-form="accounting" data-kind="setup" data-company="${esc(c)}" data-revision="${accS().revision}"><p>${esc(companyName(c))}</p>${accInput(L('記帳幣別（3 碼，如 USD、KHR）','Book currency (3 letters, e.g. USD, KHR)','រូបិយប័ណ្ណ (៣តួ ឧ. USD, KHR)'),'currency',book?.currency||'','text','maxlength="3" pattern="[A-Za-z]{3}" required')}${selectField(L('金額小數位數','Amount decimal places','ចំនួនខ្ទង់ទសភាគ'),'precision',[0,1,2,3,4].map(v=>[String(v),String(v)]),book?String(book.precision):'',true)}${accInput(L('帳套起始日／期初日','Book opening date','ថ្ងៃចាប់ផ្តើមបញ្ជី'),'openingDate',book?.openingDate||'','date','required')}${selectField(L('複核職位或人員','Reviewer position or person','តួនាទី ឬអ្នកពិនិត្យ'),'reviewer',options,book?.stages[0]?.selector||'',true)}${[1,2,3].map(i=>selectField(L(`第 ${i} 層核准${i>1?'（選填）':''}`,`Approval level ${i}${i>1?' (optional)':''}`,`អនុម័តកម្រិត ${i}`),'approver'+i,options,book?.stages[i]?.selector||'',i===1)).join('')}${selectField('狀態','enabled',[['true',t('啟用')],['false',t('已停用')]],String(book?.enabled??true),true)}${accNote(L('設定依據／原因','Reason / approved basis','មូលហេតុ / មូលដ្ឋាន'),'reason')}<label class="check"><input name="confirmed" type="checkbox" required>${L('以上帳套與簽核安排已經公司確認','The company has confirmed this book and approval route','ក្រុមហ៊ុនបានបញ្ជាក់បញ្ជី និងលំហូរនេះ')}</label><p class="help">${L('送審時，輸入、複核與各層核准必須有不同的授權人員；不會自動跳過空缺。','Submission requires distinct authorized people for preparation, review and each approval level. Vacancies are never skipped.','ការដាក់ស្នើត្រូវមានអ្នករៀបចំ ពិនិត្យ និងអនុម័តផ្សេងគ្នា។ មិនរំលងតួនាទីទំនេរ។')}</p>${accSubmit(t('儲存'))}</form>`)}
function accAccountForm(c,id){const a=accS().accounts.find(a=>a.id===id),parents=accS().accounts.filter(a=>a.company===c&&!a.posting&&a.id!==id);modal(L('會計科目','Account','គណនី'),`<form class="form" data-form="accounting" data-kind="account" data-company="${esc(c)}" data-id="${esc(id||'')}" data-revision="${a?.revision??accS().revision}">${accInput(L('科目代碼','Account code','លេខគណនី'),'code',a?.code||'','text','required maxlength="30"')}${accInput(L('科目名稱','Account name','ឈ្មោះគណនី'),'name',a?.name||'','text','required maxlength="160"')}${selectField(L('分類','Type','ប្រភេទ'),'type',Object.entries(accTypeLabels).map(([k,v])=>[k,accText(v)]),a?.type||'',true)}${selectField(L('正常餘額性質','Normal balance','ប្រភេទសមតុល្យ'),'normal',[['debit',L('借方','Debit','ឥណពន្ធ')],['credit',L('貸方','Credit','ឥណទាន')]],a?.normal||'',true)}${selectField(L('上層彙總科目（選填）','Parent group (optional)','គណនីក្រុមមេ (ស្រេចចិត្ត)'),'parentCode',parents.map(a=>[a.code,a.code+' '+a.name]),a?.parentCode||'')}${selectField(L('科目用途','Account use','ការប្រើគណនី'),'posting',[['true',L('明細：可以入帳','Detail: posting allowed','លម្អិត៖ អាចកត់ត្រា')],['false',L('彙總：不可直接入帳','Group: no direct posting','ក្រុម៖ មិនកត់ត្រាផ្ទាល់')]],String(a?.posting??true),true)}${selectField('狀態','enabled',[['true',t('啟用')],['false',t('已停用')]],String(a?.enabled??true),true)}${accInput(L('中文科目名稱（選填）','Chinese account name (optional)','ឈ្មោះគណនីចិន (ស្រេចចិត្ត)'),'nameZh',a?.nameZh||'','text','maxlength="160"')}${accInput(L('報表分類（選填）','Report group (optional)','ក្រុមរបាយការណ៍ (ស្រេចចិត្ត)'),'reportGroup',a?.reportGroup||'','text','maxlength="100"')}${accInput(L('科目類別（選填）','Category (optional)','ប្រភេទ (ស្រេចចិត្ត)'),'category',a?.category||'','text','maxlength="100"')}${selectField(L('現金流量分類','Cash flow classification','ប្រភេទលំហូរសាច់ប្រាក់'),'cashFlowGroup',Object.entries(accCashFlowLabels).map(([key,label])=>[key,accText(label)]),a?.cashFlowGroup||'unclassified',true)}${accSubmit(t('儲存'))}</form>`)}
function accLine(l={},book){return `<div class="acc-line" data-acc-line><label>${L('科目代碼／名稱搜尋','Account code / name search','ស្វែងរកលេខ / ឈ្មោះគណនី')}<input name="lineAccount" list="acc-code-options" value="${esc(l.accountCode||'')}" maxlength="30" required autocomplete="off"></label><label>${L('摘要','Line description','សង្ខេប')}<input name="lineDescription" value="${esc(l.description||'')}" maxlength="500"></label><label>${L('借方','Debit','ឥណពន្ធ')}<input name="lineDebit" inputmode="decimal" value="${esc(l.debit===undefined?'':accDecimal(l.debit,book.precision))}" placeholder="0"></label><label>${L('貸方','Credit','ឥណទាន')}<input name="lineCredit" inputmode="decimal" value="${esc(l.credit===undefined?'':accDecimal(l.credit,book.precision))}" placeholder="0"></label>${accJournalExtra(l)}<button type="button" data-action="acc-remove">${L('移除','Remove','ដកចេញ')}</button></div>`}
function accEntryForm(c,id,mode){const r=accS().entries.find(e=>e.id===id);c=r?.company||c;const book=accBook(c),sourceOptions=accS().sources.filter(s=>s.company===c&&(!s.linked||r?.sourceId===s.id));if(!book?.enabled)throw new Error(L('請先啟用帳套。','Configure the book first.','កំណត់បញ្ជីជាមុន។'));modal(L('填寫傳票','Prepare voucher','រៀបចំប័ណ្ណ'),`<form class="form" data-form="accounting" data-kind="${mode==='revise'?'revise':'save'}" data-company="${esc(c)}" data-id="${esc(id||'')}" data-revision="${r?.revision||0}"><p>${esc(companyName(c))} · ${esc(book.currency)}</p>${selectField(L('傳票種類','Voucher kind','ប្រភេទប័ណ្ណ'),'kind',[['general',L('一般傳票','General voucher','ប័ណ្ណទូទៅ')],['opening',L('期初餘額','Opening balances','សមតុល្យដើម')]],r?.kind||'general',true)}${accInput(L('傳票日期','Voucher date','កាលបរិច្ឆេទប័ណ្ណ'),'date',r?.date||'','date','required')}${accInput(L('傳票摘要','Voucher description','សង្ខេបប័ណ្ណ'),'description',r?.description||'','text','required maxlength="1000"')}${accInput(L('單據／外部參考號','Document / external reference','ឯកសារ / លេខយោង'),'reference',r?.reference||'','text','maxlength="150"')}${selectField(L('已核准來源申請（選填）','Approved source request (optional)','សំណើប្រភពបានអនុម័ត (ស្រេចចិត្ត)'),'sourceId',sourceOptions.map(s=>[s.id,s.title+' · '+s.id]),r?.sourceId||'')}<p class="help">${L('來源只建立追溯關聯；請按實際業務選科目、填入借貸金額，不會自動付款或代填會計分錄。','Linking retains traceability. Choose accounts and amounts for the actual transaction; no payment or automatic mapping occurs.','តំណភ្ជាប់សម្រាប់តាមដាន។ ជ្រើសគណនី និងទឹកប្រាក់តាមប្រតិបត្តិការពិត; មិនទូទាត់ឬបំពេញដោយស្វ័យប្រវត្តិ។')}</p><datalist id="acc-code-options">${accS().accounts.filter(a=>a.company===c&&a.enabled&&a.posting).sort((a,b)=>a.code.localeCompare(b.code)).map(a=>`<option value="${esc(a.code)}">${esc(a.name)}</option>`).join('')}</datalist><div class="acc-lines" data-acc-lines>${(r?.lines||[{},{}]).map(l=>accLine(l,book)).join('')}</div><button type="button" data-action="acc-add" data-company="${esc(c)}">＋ ${L('新增一筆分錄','Add line','បន្ថែមបន្ទាត់')}</button><div class="acc-total" data-acc-total aria-live="polite"></div>${mode==='revise'?accNote(L('修改原因（保留原分錄）','Reason for revision (original retained)','មូលហេតុកែ (រក្សាដើម)'),'reason'):''}${accSubmit(L('儲存傳票','Save voucher','រក្សាប័ណ្ណ'))}</form>`);accUpdateTotal()}
function accUpdateTotal(){const f=$('#dialog form');if(!f?.querySelector('[data-acc-lines]'))return;const book=accBook(f.dataset.company),rows=[...f.querySelectorAll('[data-acc-line]')];let debit=0,credit=0;rows.forEach(row=>{debit+=Number(row.querySelector('[name=lineDebit]').value)||0;credit+=Number(row.querySelector('[name=lineCredit]').value)||0});f.querySelector('[data-acc-total]').textContent=L('借方 / 貸方','Debit / credit','ឥណពន្ធ / ឥណទាន')+` : ${debit.toFixed(book.precision)} / ${credit.toFixed(book.precision)} ${book.currency} · `+(Math.round(debit*10**book.precision)===Math.round(credit*10**book.precision)&&debit>0?L('平衡','Balanced','មានតុល្យភាព'):L('請核對借貸金額','Check debit and credit','ពិនិត្យឥណពន្ធ និងឥណទាន'))}
function accActionForm(id,kind){const r=accS().entries.find(e=>e.id===id);modal(accText(accActionLabels[kind]),`<form class="form" data-form="accounting" data-kind="${kind}" data-company="${esc(r.company)}" data-id="${esc(id)}" data-revision="${r.revision}"><p>${esc(r.number||r.id)} · ${esc(r.description)}</p>${kind==='post'?`<p class="acc-warning">${L('入帳後會影響財務報表，原分錄不能直接修改；更正需另建沖回傳票。此操作不會移轉款項。','Posting changes the reports and makes lines immutable. Corrections require a reversal. This does not transfer funds.','កត់ត្រាប្តូររបាយការណ៍ និងមិនអាចកែផ្ទាល់។ ត្រូវមានប័ណ្ណត្រឡប់។ មិនផ្ទេរប្រាក់។')}</p>`:''}${kind==='reverse'?accInput(L('沖回傳票日期','Reversal date','ថ្ងៃប័ណ្ណត្រឡប់'),'date','','date','required'):''}${accNote(L('處理說明','Decision note','កំណត់សម្គាល់'),'reason','',kind!=='submit')}${accSubmit(accText(accActionLabels[kind]))}</form>`)}
function accCloseForm(c){const book=accBook(c);modal(L('鎖定已結帳期間','Close accounting period','បិទរយៈពេលគណនេយ្យ'),`<form class="form" data-form="accounting" data-kind="close" data-company="${esc(c)}" data-revision="${book.revision}"><p>${L('期間內所有傳票必須已入帳或作廢。結帳後不可新增或修改該日期內的分錄；更正在之後的開放期間處理。','All vouchers in the period must be posted or void. Closed dates reject new entries; corrections use a later open period.','ប័ណ្ណក្នុងរយៈពេលត្រូវកត់ត្រា ឬមោឃៈ។ ថ្ងៃបិទមិនទទួលថ្មី; កែនៅរយៈពេលបើកក្រោយ។')}</p>${accInput(L('結帳截至日','Close through','បិទរហូតដល់'),'through','','date','required')}${accNote(L('結帳依據／原因','Closing basis / reason','មូលដ្ឋាន / មូលហេតុ'),'reason')}${accSubmit(L('鎖定期間','Close period','បិទរយៈពេល'))}</form>`)}
function accImportForm(c,kind){modal(L('匯入 CSV','Import CSV','នាំចូល CSV'),`<form class="form" data-form="accounting" data-kind="${kind==='accounts'?'importaccounts':'import'}" data-company="${esc(c)}" data-revision="${accS().revision}"><p>${esc(companyName(c))} · ${kind==='accounts'?L('科目表','Chart of accounts','បញ្ជីគណនី'):L('傳票草稿','Voucher drafts','ព្រាងប័ណ្ណ')}</p><label>${L('UTF-8 CSV 檔案（最多 150 KB）','UTF-8 CSV file (max 150 KB)','ឯកសារ UTF-8 CSV (អតិបរមា 150 KB)')}<input type="file" accept=".csv,text/csv" data-acc-file></label><label>${L('或貼上 CSV 內容','Or paste CSV content','ឬបិទភ្ជាប់ CSV')}<textarea name="csv" rows="7" maxlength="150000" required spellcheck="false"></textarea></label><button type="button" data-action="acc-preview">${L('先檢查與預覽','Validate & preview','ពិនិត្យ និងមើលជាមុន')}</button><div data-acc-preview aria-live="polite"></div><label class="check"><input type="checkbox" name="confirmed" required>${L('已核對預覽，確認匯入這家公司','I reviewed the preview and confirm this company','បានពិនិត្យ និងបញ្ជាក់ក្រុមហ៊ុននេះ')}</label>${accSubmit(L('確認匯入','Confirm import','បញ្ជាក់នាំចូល'))}</form>`)}
async function accPreview(){const f=$('#dialog form'),kind=f.dataset.kind==='importaccounts'?'previewaccounts':'preview',p=await api('accounting/'+kind,{company:f.dataset.company,csv:f.elements.csv.value});f.dataset.hash=p.hash;f.dataset.previewCsv=f.elements.csv.value;f.querySelector('[data-acc-preview]').innerHTML=`<p>${p.rows} ${L('筆資料','rows','ជួរ')} · ${p.errors.length} ${L('個錯誤','errors','កំហុស')}</p>${p.errors.length?`<ul class="acc-import-errors">${p.errors.map(e=>`<li>${L('第','Row','ជួរ')} ${e.row}：${esc(e.message)}</li>`).join('')}</ul>`:`<p class="badge green">${L('檢查通過，可以確認匯入','Validation passed; ready to import','ពិនិត្យរួច អាចនាំចូល')}</p>`}${p.vouchers?`<ul>${p.vouchers.map(v=>`<li>${esc(v.key)} · ${esc(v.date)} · ${accAmount(v.total,accBook(f.dataset.company))} ${esc(v.currency)}</li>`).join('')}</ul>`:''}`;f.dataset.previewValid=String(p.errors.length===0)}
async function accDownload(c,kind,start,end){const r=await api('accounting/export',{company:c,kind,start,end}),url=URL.createObjectURL(new Blob([r.csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=r.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function submitAccounting(f,values){const v=Object.fromEntries(values),kind=f.dataset.kind,company=f.dataset.company,base={...v,company,id:f.dataset.id||undefined,revision:Number(f.dataset.revision)};let result;
 if(kind==='setup'){const selectors=[v.approver1,v.approver2,v.approver3];if(v.approver3&&!v.approver2)throw new Error(L('請依順序設定核准層級。','Set approval levels in order.','កំណត់កម្រិតតាមលំដាប់។'));result=await api('accounting/setup',{...base,precision:Number(v.precision),enabled:v.enabled==='true',confirmed:v.confirmed==='on',stages:[{type:'review',selector:v.reviewer},...selectors.filter(Boolean).map(selector=>({type:'approve',selector}))]})}
 else if(kind==='applytemplate')result=await api('accounting/applytemplate',{...base,confirmed:v.confirmed==='on'});
 else if(kind==='saveopening'){const prior=accountingOpeningPreview,values=accOpeningValues(f);if(!prior?.canSave||prior.company!==company||prior.templateId!==v.templateId||JSON.stringify(prior.values)!==JSON.stringify(values))throw new Error(L('請先核對目前的期初餘額。','Validate the current opening balances first.','ពិនិត្យសមតុល្យដើមបច្ចុប្បន្នជាមុន។'));result=await api('accounting/saveopening',{...base,values,hash:prior.hash,confirmed:v.confirmed==='on'})}
 else if(['importtemplate','importworkbook'].includes(kind)){const prior=accountingWorkbookImport,file=f.querySelector('[data-acc-workbook-file]').files[0];if(!prior?.canSave||prior.company!==company||prior.kind!==kind||prior.file!==file)throw new Error(L('請先讀取並核對目前的檔案。','Read and validate this file first.','អាន និងពិនិត្យឯកសារនេះជាមុន។'));if(kind==='importworkbook'){const match=accWorkbookSourceMatch(prior.data,company);if((prior.data.errors||[]).length||!match.ok)throw new Error(match.errors[0]?.message||L('檔案仍有錯誤，請重新核對。','The file still contains errors. Validate it again.','ឯកសារនៅមានកំហុស។ ពិនិត្យឡើងវិញ។'))}result=await api('accounting/'+kind,{...base,...(kind==='importtemplate'?{template:prior.data.template}:{journals:prior.data.journals}),hash:prior.preview.hash,confirmed:v.confirmed==='on'})}
 else if(kind==='account')result=await api('accounting/account',{...base,enabled:v.enabled==='true',posting:v.posting==='true'});
 else if(kind==='save'||kind==='revise'){const lines=[...f.querySelectorAll('[data-acc-line]')].map(row=>({accountCode:row.querySelector('[name=lineAccount]').value,description:row.querySelector('[name=lineDescription]').value,debit:row.querySelector('[name=lineDebit]').value||'0',credit:row.querySelector('[name=lineCredit]').value||'0',...Object.fromEntries([...row.querySelectorAll('[data-acc-meta]')].map(n=>[n.dataset.accMeta,n.value]))}));result=await api('accounting/'+kind,{...base,currency:accBook(company).currency,lines})}
 else if(kind==='import'||kind==='importaccounts'){if(f.dataset.previewValid!=='true'||f.dataset.previewCsv!==v.csv)throw new Error(L('請先預覽目前內容並修正錯誤。','Preview the current content and resolve errors first.','ពិនិត្យមាតិកាបច្ចុប្បន្ន និងកែកំហុសជាមុន។'));result=await api('accounting/'+kind,{...base,hash:f.dataset.hash,confirmed:v.confirmed==='on'})}
 else if(kind==='report'){result=await api('accounting/report',{company,start:v.start,end:v.end});accountingReportCache={company,revision:accS().revision,report:result.report};return result}
 else result=await api('accounting/'+kind,base);
 accountingReportCache=null;if(result?.id&&(kind==='save'||kind==='revise'||kind==='reverse'||kind==='saveopening'))location.hash=href('finance',{company,tab:'journals',detail:result.id});return result;
}
function initializeAccountingUI(){const previous=finance;finance=function(){const tab=route().tab;if(!tab||['journals','accounts','reports','opening','imports','book'].includes(tab))return renderAccounting();return accStyles+accTabs()+previous()};
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||!b.dataset.action.startsWith('acc-'))return;try{const c=b.dataset.company||accCompany(),id=b.dataset.id;switch(b.dataset.action){case'acc-setup':accSetupForm(c);break;case'acc-workbook':accWorkbookForm(c,b.dataset.kind);break;case'acc-apply-template':accApplyTemplateForm(c,id);break;case'acc-opening':accOpeningForm(c);break;case'acc-preview-opening':b.disabled=true;try{await accPreviewOpening()}finally{b.disabled=false}break;case'acc-workbook-preview':b.disabled=true;try{await accWorkbookPreview()}finally{b.disabled=false}break;case'acc-account':accAccountForm(c,id);break;case'acc-entry':accEntryForm(c,id,b.dataset.kind);break;case'acc-act':accActionForm(id,b.dataset.kind);break;case'acc-close':accCloseForm(c);break;case'acc-import':accImportForm(c,b.dataset.kind);break;case'acc-preview':b.disabled=true;try{await accPreview()}finally{b.disabled=false}break;case'acc-export':await accDownload(c,b.dataset.kind,b.dataset.start,b.dataset.end);break;case'acc-add':{const wrap=$('#dialog [data-acc-lines]');if(wrap.children.length>=150)throw new Error(L('最多 150 筆分錄。','Maximum 150 lines.','អតិបរមា១៥០បន្ទាត់។'));wrap.insertAdjacentHTML('beforeend',accLine({},accBook(c)));break}case'acc-remove':{const wrap=b.closest('[data-acc-lines]');if(wrap.children.length<=2)throw new Error(L('至少保留兩筆分錄。','Keep at least two lines.','រក្សាយ៉ាងហោចណាស់២បន្ទាត់។'));b.closest('[data-acc-line]').remove();accUpdateTotal();break}}}catch(error){if(error.code==='STALE_SESSION')return;const box=$('#dialog .error');if($('#dialog').open&&box)box.textContent=error.message;else flash(error.message)}});
 document.addEventListener('input',e=>{if(e.target.matches('[data-acc-search]')){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-acc-row]').forEach(r=>r.hidden=!r.dataset.search.includes(q))}if(e.target.closest('[data-acc-line]'))accUpdateTotal()});
 document.addEventListener('change',async e=>{if(e.target.matches('[data-acc-workbook-file]')){accountingWorkbookImport=null;const box=e.target.closest('form').querySelector('[data-acc-workbook-preview]');if(box)box.textContent='';return}if(!e.target.matches('[data-acc-file]'))return;const epoch=workspaceAuthEpoch;try{const file=e.target.files[0];if(!file)return;if(file.size>150000||!file.name.toLowerCase().endsWith('.csv'))throw new Error(L('請選擇 150 KB 以下的 CSV。','Select a CSV file under 150 KB.','ជ្រើស CSV ក្រោម១៥០ KB។'));const f=e.target.closest('form');const text=await file.text();assertWorkspaceEpoch(epoch);if(f!==$('#dialog form'))return;f.elements.csv.value=text;delete f.dataset.hash;f.dataset.previewValid='false';f.querySelector('[data-acc-preview]').innerHTML=''}catch(error){if(error.code==='STALE_SESSION')return;const box=$('#dialog .error');if(box)box.textContent=error.message}});
}

// Workbook structure is read from the authorized company response, never bundled as business data.
function accTemplate(c){return (accS().templates||[]).filter(x=>x.company===c).at(-1)||null}
function accWorkbookSourceMatch(data,c){
 const template=accTemplate(c),source=data?.template,errors=[],issue=message=>errors.push({message});
 if(!template?.applied){issue(L('請先套用並核對這家公司的科目表，再匯入金額。','Apply and verify this company’s chart before importing amounts.','ប្រើ និងពិនិត្យបញ្ជីគណនីក្រុមហ៊ុននេះមុននាំចូលទឹកប្រាក់។'));return {ok:false,errors}}
 if(!source||source.company!==c||!Array.isArray(source.accounts)){issue(L('檔案的公司或科目結構不符合目前帳套。','The workbook company or chart structure does not match this book.','ក្រុមហ៊ុន ឬរចនាសម្ព័ន្ធគណនីក្នុងឯកសារមិនត្រូវនឹងបញ្ជីនេះ។'));return {ok:false,errors}}
 const normalize=value=>String(value??'').normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase('en-US');
 const same=(a,b)=>a&&b&&a.code===b.code&&normalize(a.name)===normalize(b.name)&&a.type===b.type&&a.normal===b.normal;
 const incoming=new Map(source.accounts.map(a=>[a.code,a])),expected=template.accounts||[],installed=new Map((accS().accounts||[]).filter(a=>a.company===c).map(a=>[a.code,a]));
 if(incoming.size!==source.accounts.length||source.accounts.length!==expected.length)issue(L('檔案的科目數量或代碼與已套用科目表不同，不能直接匯入。','Account count or codes differ from the applied chart; direct import is blocked.','ចំនួន ឬលេខគណនីខុសពីបញ្ជីបានប្រើ; មិនអាចនាំចូលផ្ទាល់។'));
 for(const account of expected)if(!same(incoming.get(account.code),account)||!same(installed.get(account.code),account))issue(L('科目對照不一致：','Account mapping differs: ','ការផ្គូផ្គងគណនីខុស៖ ')+account.code+' · '+account.name+L('。請核對 Excel 的科目順序、名稱、分類與借貸性質。','; check the workbook account order, names, types and debit/credit nature.','; ពិនិត្យលំដាប់ ឈ្មោះ ប្រភេទ និងឥណពន្ធ/ឥណទាន។'));
 return {ok:!errors.length,errors};
}
function accOpeningSource(c){const imported=accountingWorkbookImport?.company===c?accountingWorkbookImport:null,data=imported?.data;if(!data)return {data:null,values:{},errors:[],usable:false};const match=accWorkbookSourceMatch(data,c),errors=[...(data.errors||[]),...(imported.preview?.errors||[]),...match.errors];return {data,values:errors.length?{}:data.openingValues||{},errors,usable:!errors.length}}
function accName(row){return lang==='zh'&&row.nameZh?row.nameZh:row.name||row.label||row.code||''}
function accTemplateCard(c){const template=accTemplate(c),book=accBook(c);if(!template)return accCap(c,'configure')?`<section class="card section-gap"><h2>${L('公司的 Excel 記帳格式','Company Excel format','ទម្រង់ Excel របស់ក្រុមហ៊ុន')}</h2><p>${L('上傳公司的 Journal 與財報工作簿，先核對科目及前期餘額。','Upload the company Journal and financial workbook to check accounts and prior balances.','ផ្ទុកសៀវភៅ Journal និងរបាយការណ៍ ដើម្បីពិនិត្យគណនី និងសមតុល្យមុន។')}</p>${button(L('讀取 Excel 工作簿','Read Excel workbook','អានសៀវភៅ Excel'),'acc-workbook',`data-company="${esc(c)}"`)}</section>`:'';return `<section class="card section-gap"><div class="card-title"><h2>${L('公司記帳範本','Company accounting template','គំរូគណនេយ្យក្រុមហ៊ុន')}</h2><span class="badge ${template.applied?'green':'amber'}">${template.applied?L('已套用科目','Accounts applied','បានប្រើគណនី'):L('待套用科目','Accounts not applied','មិនទាន់ប្រើគណនី')}</span></div><p>${esc(template.sourceName)} · ${template.accounts.length} ${L('個科目','accounts','គណនី')}</p><p class="sub">${L('科目表、前期餘額與 Journal 記帳互相連接；試算、損益、資產負債及現金流量都使用同一家公司的已入帳分錄。','The chart, prior balances and Journal connect to the trial balance, profit & loss, balance sheet and cash flow. Reports use posted entries from this company.','គណនី សមតុល្យមុន និង Journal ភ្ជាប់ទៅតុល្យភាព ចំណេញខាត តុល្យការ និងលំហូរសាច់ប្រាក់។')}</p>${accCap(c,'configure')?`<div class="button-row">${button(L('讀取另一份 Excel','Read another Excel file','អាន Excel ផ្សេង'),'acc-workbook',`data-company="${esc(c)}"`,false)}${!template.applied&&book?.enabled?button(L('套用這份科目表','Apply this chart','ប្រើបញ្ជីគណនីនេះ'),'acc-apply-template',`data-company="${esc(c)}" data-id="${esc(template.id)}"`):!book?.enabled?button(L('設定帳套與簽核','Configure book & approvals','កំណត់បញ្ជី និងអនុម័ត'),'acc-setup',`data-company="${esc(c)}"`):''}</div>`:''}</section>`}
function accApplyTemplateForm(c,id){const template=(accS().templates||[]).find(t=>t.company===c&&t.id===id);if(!template)throw new Error(L('找不到這家公司的範本。','Company template not found.','រកមិនឃើញគំរូក្រុមហ៊ុន។'));modal(L('套用科目表','Apply chart of accounts','ប្រើបញ្ជីគណនី'),`<form class="form" data-form="accounting" data-kind="applytemplate" data-company="${esc(c)}" data-revision="${accS().revision}"><input type="hidden" name="templateId" value="${esc(id)}"><p>${esc(companyName(c))} · ${template.accounts.length} ${L('個科目','accounts','គណនី')}</p><p>${L('這一步建立科目及報表分類。期初餘額與交易會另外填寫、送審，不會在這一步入帳。','This creates accounts and report classifications. Opening balances and transactions are entered and reviewed separately.','បង្កើតគណនី និងប្រភេទរបាយការណ៍។ សមតុល្យដើម និងប្រតិបត្តិការត្រូវបំពេញ និងពិនិត្យដោយឡែក។')}</p><label class="check"><input type="checkbox" name="confirmed" required>${L('已核對公司與科目表','Company and chart checked','បានពិនិត្យក្រុមហ៊ុន និងគណនី')}</label>${accSubmit(L('套用科目表','Apply chart','ប្រើគណនី'))}</form>`)}
function accOpeningView(c,book){const template=accTemplate(c),rows=accS().entries.filter(e=>e.company===c&&e.kind==='opening'&&e.status!=='void');return `<section class="card"><h2>${L('前期餘額，轉成期初傳票','Prior balances to opening voucher','ពីសមតុល្យមុន ទៅប័ណ្ណដើម')}</h2><p>${L('把前一年度結束時的資產、負債與權益填在這裡。借貸核對平衡後，建立期初草稿，再依原本簽核流程入帳。','Enter assets, liabilities and equity at the prior year end. Balanced amounts become an opening draft, then follow the normal review, approval and posting route.','បញ្ចូលទ្រព្យសកម្ម បំណុល និងមូលធនចុងឆ្នាំមុន។ ពេលមានតុល្យភាព បង្កើតព្រាង ហើយពិនិត្យ អនុម័ត និងកត់ត្រា។')}</p><p><strong>${L('期初日','Opening date','ថ្ងៃដើម')}：</strong>${esc(book.openingDate)}</p><div class="acc-flow"><span>${L('① 填前期餘額','① Enter prior balances','① បញ្ចូលសមតុល្យមុន')}</span><span>${L('② 核對借貸','② Check balance','② ពិនិត្យតុល្យភាព')}</span><span>${L('③ 建立期初草稿','③ Create opening draft','③ បង្កើតព្រាងដើម')}</span><span>${L('④ 複核、核准、入帳','④ Review, approve, post','④ ពិនិត្យ អនុម័ត កត់ត្រា')}</span></div>${rows.length?rows.map(e=>`<p><a href="${href('finance',{company:c,tab:'journals',detail:e.id})}">${esc(e.number||e.id)} · ${accText(accLabels[e.status])} →</a></p>`).join(''):accCap(c,'create')&&template?.applied?button(L('填寫前期餘額','Enter prior balances','បញ្ចូលសមតុល្យមុន'),'acc-opening',`data-company="${esc(c)}"`):`<p class="acc-warning">${L('先在「科目與試算」套用公司的科目表。','Apply the company chart under Accounts & trial first.','ប្រើបញ្ជីគណនីក្រុមហ៊ុនជាមុន។')}</p>`}</section>`}
function accOpeningForm(c){const template=accTemplate(c);if(!template?.applied)throw new Error(L('請先套用科目表。','Apply the chart first.','សូមប្រើបញ្ជីគណនីជាមុន។'));const source=accOpeningSource(c),saved=source.values;accountingOpeningPreview=null;modal(L('填寫前期餘額','Enter prior balances','បញ្ចូលសមតុល្យមុន'),`<form class="form" data-form="accounting" data-kind="saveopening" data-company="${esc(c)}" data-revision="${accS().revision}"><input name="templateId" type="hidden" value="${esc(template.id)}"><p>${esc(companyName(c))} · ${esc(accBook(c).currency)} · ${esc(accBook(c).openingDate)}</p>${source.data&&!source.usable?`<p class="acc-warning">${L('檔案有錯誤或科目對照不一致，未帶入任何前期金額。請重新核對檔案，或依原始帳表手動填寫。','The file has errors or a different chart. No prior amounts were prefilled. Correct the file or enter balances manually from the source records.','ឯកសារមានកំហុស ឬគណនីមិនត្រូវគ្នា។ មិនបានបញ្ចូលទឹកប្រាក់មុនទេ។ កែឯកសារ ឬបំពេញដោយដៃពីកំណត់ត្រាដើម។')}</p>`:''}<p class="help">${L('依欄位的借／貸性質填正數，反向餘額填負數。留空表示尚未提供；填 0 表示已確認為零。','Enter a positive amount for the stated debit/credit side; use a negative value for the opposite side. Blank means not provided; 0 means a confirmed zero.','បញ្ចូលវិជ្ជមានតាមឥណពន្ធ/ឥណទាន; អវិជ្ជមានសម្រាប់ផ្ទុយ។ ទទេគឺមិនបានផ្តល់; 0 គឺបញ្ជាក់សូន្យ។')}</p>${template.openingFields.map(field=>`<label>${esc(field.label)} <small>${esc(field.sourceCell||'')} · ${field.normal==='credit'?L('貸方','Credit','ឥណទាន'):L('借方','Debit','ឥណពន្ធ')}</small><input data-acc-opening-field="${esc(field.id)}" name="opening-${esc(field.id)}" inputmode="decimal" value="${esc(saved[field.id]??'')}" autocomplete="off" placeholder="${L('尚未提供','Not provided','មិនបានផ្តល់')}"></label>`).join('')}<button type="button" data-action="acc-preview-opening">${L('核對借貸與缺漏','Check balance and missing values','ពិនិត្យតុល្យភាព និងតម្លៃខ្វះ')}</button><div data-acc-opening-preview aria-live="polite"></div><label class="check"><input type="checkbox" name="confirmed" required>${L('已核對金額，建立期初草稿送審','Amounts checked; create a draft for review','បានពិនិត្យទឹកប្រាក់ បង្កើតព្រាងសម្រាប់ពិនិត្យ')}</label>${accSubmit(L('建立期初草稿','Create opening draft','បង្កើតព្រាងដើម'))}</form>`)}
function accOpeningValues(form){return Object.fromEntries([...form.querySelectorAll('[data-acc-opening-field]')].filter(n=>n.value.trim()!=='').map(n=>[n.dataset.accOpeningField,n.value.trim()]))}
async function accPreviewOpening(){const f=$('#dialog form'),values=accOpeningValues(f),payload={company:f.dataset.company,templateId:f.elements.templateId.value,values},r=await api('accounting/previewopening',payload);accountingOpeningPreview={...payload,revision:Number(f.dataset.revision),hash:r.hash,canSave:r.canSave};const book=accBook(payload.company);f.querySelector('[data-acc-opening-preview]').innerHTML=`<p class="acc-total">${L('借方／貸方','Debit / credit','ឥណពន្ធ / ឥណទាន')} ${accAmount(r.totalDebit,book)} / ${accAmount(r.totalCredit,book)} · ${L('差額','Difference','ភាពខុសគ្នា')} ${accAmount(r.difference,book)}</p>${(r.errors||[]).length?`<ul class="acc-import-errors">${r.errors.map(e=>`<li>${esc(e.message||e)}</li>`).join('')}</ul>`:''}${r.missing?.length?`<p class="acc-warning">${r.missing.length} ${L('個餘額尚未提供。請核對後補齊，已確認為零的欄位填 0。','balances have not been provided. Complete them; enter 0 only for confirmed zeros.','សមតុល្យមិនទាន់ផ្តល់។ បំពេញ ហើយដាក់ 0 តែពេលបញ្ជាក់សូន្យ។')}</p><details><summary>${L('查看缺少的欄位','Show missing values','បង្ហាញតម្លៃខ្វះ')}</summary><ul>${r.missing.map(x=>`<li>${esc(x.label)} · ${esc(x.sourceCell||'')}</li>`).join('')}</ul></details>`:''}${r.canSave?`<p class="badge green">${L('核對通過，可建立草稿','Validated; draft can be created','ពិនិត្យរួច អាចបង្កើតព្រាង')}</p>`:''}`}
function accFinancialRows(rows,book,{compare=false,months=[]}={}){return table(compare?[L('科目','Account','គណនី'),L('期初比較數','Opening comparator','សមតុល្យដើមប្រៀបធៀប'),L('截止日餘額','Closing balance','សមតុល្យចុង'),L('變動','Change','ការប្រែប្រួល')]:[L('科目','Account','គណនី'),...months,L('期間合計','Period total','សរុបរយៈពេល')],rows.map(row=>`<tr><td><strong>${esc(accName(row))}</strong><small>${esc(row.code)}${row.reportGroup?' · '+esc(accReportGroupName(row.reportGroup)):''}</small></td>${compare?[row.previous,row.current,row.change].map(v=>`<td class="money">${accAmount(v,book)}</td>`).join(''):(row.amounts||[]).map(v=>`<td class="money">${accAmount(v,book)}</td>`).join('')+`<td class="money"><strong>${accAmount(row.total,book)}</strong></td>`}</tr>`))}
function accMonthlyProfit(r,book){const p=r.profitMonthly;if(!p)return '';const months=p.months.map(m=>m.slice(0,7)),sumGroup=group=>months.map((_,i)=>p.rows.filter(x=>x.type==='expense'&&x.reportGroup===group).reduce((sum,x)=>sum+(x.amounts[i]||0),0)),cost=sumGroup('cost'),operating=sumGroup('operating_expense'),finance=sumGroup('finance_cost'),other=p.expense.map((n,i)=>n-cost[i]-operating[i]-finance[i]),totals=[[L('收入合計','Total revenue','ចំណូលសរុប'),p.revenue],[L('營業成本','Cost of sales / services','ថ្លៃដើមលក់ / សេវា'),cost],[L('毛利','Gross profit','ប្រាក់ចំណេញដុល'),p.revenue.map((n,i)=>n-cost[i])],[L('營業費用','Operating expenses','ចំណាយប្រតិបត្តិការ'),operating],[L('財務成本及稅費','Finance costs and taxes','ថ្លៃហិរញ្ញវត្ថុ និងពន្ធ'),finance],...(other.some(Boolean)?[[L('其他／待分類費用','Other / unclassified expenses','ចំណាយផ្សេង / មិនបានចាត់ថ្នាក់'),other]]:[]),[L('本期損益','Period result','លទ្ធផលរយៈពេល'),p.result]];return `<h2>${L('每月損益','Monthly profit & loss','ចំណេញខាតប្រចាំខែ')}</h2>`+table([L('彙總','Summary','សង្ខេប'),...months,L('期間合計','Period total','សរុបរយៈពេល')],totals.map(([label,values])=>`<tr><td><strong>${label}</strong></td>${values.map(n=>`<td class="money">${accAmount(n,book)}</td>`).join('')}<td class="money"><strong>${accAmount(values.reduce((a,b)=>a+b,0),book)}</strong></td></tr>`))+`<p class="footnote">${L('收入－成本＝毛利；毛利再減費用、財務成本及稅費＝本期損益。尚未分類的費用仍計入損益，另行列示。','Revenue minus costs gives gross profit. Expenses, finance costs and taxes then give the period result. Unclassified expenses remain included and are shown separately.','ចំណូលដកថ្លៃដើមជាចំណេញដុល។ បន្ទាប់ដកចំណាយ ថ្លៃហិរញ្ញវត្ថុ និងពន្ធជាលទ្ធផលរយៈពេល។ ចំណាយមិនបានចាត់ថ្នាក់នៅតែរាប់បញ្ចូល។')}</p>`+accFinancialRows(p.rows,book,{months})}
function accComparativeBalance(r,book){const p=r.comparativeBalance;if(!p)return '';const totals=[['assets',L('資產合計','Total assets','ទ្រព្យសកម្មសរុប')],['liabilities',L('負債合計','Total liabilities','បំណុលសរុប')],['equity',L('權益合計（未含本期損益）','Equity before unclosed result','មូលធនមុនលទ្ធផលមិនបិទ')],['unclosedResult',L('未結轉損益','Unclosed result','លទ្ធផលមិនបិទ')],['difference',L('資產－負債－權益－未結轉損益','Assets − liabilities − equity − unclosed result','ទ្រព្យ − បំណុល − មូលធន − លទ្ធផលមិនបិទ')]];return `<p class="sub">${L('比較日','Comparison date','ថ្ងៃប្រៀបធៀប')}：${esc(p.openingIncluded?p.start:p.previousDate)} → ${esc(p.end)} · ${L(p.openingIncluded?'比較數包含起始日的期初傳票。':'比較數為起始日前一日餘額。',p.openingIncluded?'Comparison includes the opening voucher on the start date.':'Comparison is the balance on the day before the start date.',p.openingIncluded?'ការប្រៀបធៀបរួមប័ណ្ណដើមនៅថ្ងៃចាប់ផ្តើម។':'ការប្រៀបធៀបជាសមតុល្យមួយថ្ងៃមុនថ្ងៃចាប់ផ្តើម។')}</p>`+table([L('彙總','Summary','សង្ខេប'),L('期初比較數','Opening comparator','សមតុល្យដើមប្រៀបធៀប'),L('截止日餘額','Closing balance','សមតុល្យចុង'),L('變動','Change','ការប្រែប្រួល')],totals.map(([key,label])=>`<tr><td><strong>${label}</strong></td>${[p.previous[key],p.current[key],p.current[key]-p.previous[key]].map(n=>`<td class="money"><strong>${accAmount(n,book)}</strong></td>`).join('')}</tr>`))+accFinancialRows(p.rows,book,{compare:true})}
function accCashflowView(r,book){const cf=r.cashflow;if(!cf)return empty(L('尚無現金流量報表','Cash flow report unavailable','មិនមានរបាយការណ៍លំហូរសាច់ប្រាក់'));const labels={netIncome:L('本期損益','Net income','ចំណេញសុទ្ធ'),adjustments:L('非現金調整','Non-cash adjustments','កែសម្រួលមិនមែនសាច់ប្រាក់'),workingCapital:L('營運資金變動','Working capital movements','បម្រែបម្រួលទុនបង្វិល'),operating:L('營業活動','Operating activities','សកម្មភាពប្រតិបត្តិការ'),investing:L('投資活動','Investing activities','សកម្មភាពវិនិយោគ'),financing:L('籌資活動','Financing activities','សកម្មភាពហិរញ្ញប្បទាន'),calculatedChange:L('計算的現金變動','Calculated cash change','បម្រែបម្រួលសាច់ប្រាក់គណនា'),openingCash:L('期初現金','Opening cash','សាច់ប្រាក់ដើម'),closingCash:L('期末現金','Closing cash','សាច់ប្រាក់ចុង'),actualChange:L('帳上現金變動','Cash change in ledger','បម្រែបម្រួលសាច់ប្រាក់ក្នុងបញ្ជី'),residual:L('待核對差額','Unreconciled difference','ភាពខុសគ្នាត្រូវផ្ទៀងផ្ទាត់')};return `<section class="card"><div class="card-title"><h2>${L('現金流量｜間接法草稿','Cash flow | indirect-method draft','លំហូរសាច់ប្រាក់ | ព្រាងវិធីប្រយោល')}</h2><span class="badge amber">${L('待財務核對分類','Classification review needed','ត្រូវពិនិត្យប្រភេទ')}</span></div><p>${L('從已入帳資料計算。先確認哪些科目屬於現金、營業、投資及籌資；未分類與差額會列出來。','Calculated from posted entries. Confirm cash, operating, investing and financing classifications; unmapped accounts and differences remain visible.','គណនាពីកំណត់ត្រារួច។ បញ្ជាក់ប្រភេទសាច់ប្រាក់ ប្រតិបត្តិការ វិនិយោគ និងហិរញ្ញប្បទាន។')}</p><dl class="details">${Object.entries(labels).map(([key,label])=>`<div><dt>${label}</dt><dd><strong>${accAmount(cf[key],book)}</strong></dd></div>`).join('')}</dl></section>${cf.residual?`<p class="acc-warning">${L('仍有差額，請核對科目分類、非現金交易及期初餘額。差額未自動放入任何活動。','A difference remains. Check classifications, non-cash transactions and opening balances. It is not forced into an activity.','នៅមានភាពខុសគ្នា។ ពិនិត្យប្រភេទ ប្រតិបត្តិការមិនមែនសាច់ប្រាក់ និងសមតុល្យដើម។')}</p>`:''}${cf.warnings?.length?`<ul class="acc-import-errors">${cf.warnings.map(x=>`<li>${esc(accCashflowWarning(x.message||x))}</li>`).join('')}</ul>`:''}${cf.unmapped?.length?`<h2>${L('待分類科目','Unmapped accounts','គណនីមិនមានប្រភេទ')}</h2>`+table([L('科目','Account','គណនី'),L('金額','Amount','ទឹកប្រាក់')],cf.unmapped.map(x=>`<tr><td>${esc(x.code+' '+x.name)}</td><td class="money">${accAmount(x.amount,book)}</td></tr>`)):''}${accCashflowLinks(r)}${cf.rows?.length?`<h2>${L('計算明細','Calculation details','លម្អិតការគណនា')}</h2>`+table([L('科目','Account','គណនី'),L('分類','Classification','ប្រភេទ'),L('金額','Amount','ទឹកប្រាក់')],cf.rows.map(x=>`<tr><td>${esc(x.code+' '+x.name)}</td><td>${esc(accCashFlowLabels[x.group]?accText(accCashFlowLabels[x.group]):x.group)}</td><td class="money">${accAmount(x.amount,book)}</td></tr>`)):''}`}

function accWorkbookPanel(c,book){const template=accTemplate(c),source=accOpeningSource(c),loaded=source.data;return `<section class="card section-gap"><h2>${L('Excel 工作簿','Excel workbook','សៀវភៅ Excel')}</h2><p>${L('選擇原公司的 .xlsx 檔，先看預覽與錯誤，再決定匯入科目或傳票。報表由入帳資料重新計算。','Choose the company .xlsx file, review the preview and errors, then import the chart or voucher drafts. Reports are recalculated from posted entries.','ជ្រើសឯកសារ .xlsx ពិនិត្យជាមុន ហើយនាំចូលគណនី ឬព្រាងប័ណ្ណ។ របាយការណ៍គណនាពីកំណត់ត្រាដែលបានបញ្ចូល។')}</p><div class="button-row">${accCap(c,'configure')?button(L('讀取科目範本','Read chart template','អានគំរូគណនី'),'acc-workbook',`data-company="${esc(c)}" data-kind="importtemplate"`,false):''}${book?.enabled&&template?.applied&&accCap(c,'create')?button(L('匯入 Journal 傳票','Import Journal vouchers','នាំចូលប័ណ្ណ Journal'),'acc-workbook',`data-company="${esc(c)}" data-kind="importworkbook"`):''}${book?.enabled&&template?.applied&&accCap(c,'create')&&source.usable?button(L('帶入檔案中的前期餘額','Use prior balances from file','ប្រើសមតុល្យមុនពីឯកសារ'),'acc-opening',`data-company="${esc(c)}"`,false):''}</div>${loaded?`<p class="sub">${L('已讀取','Read','បានអាន')} ${esc(loaded.template.sourceName)} · ${loaded.journals.length} ${L('組 Journal 傳票','Journal voucher groups','ក្រុមប័ណ្ណ Journal')} · ${Object.keys(loaded.openingValues||{}).length} ${L('筆已填前期餘額','provided prior balances','សមតុល្យមុនបានផ្តល់')}</p>${!source.usable?`<p class="acc-warning">${L('此檔案尚未通過科目對照與資料檢查，不會帶入前期金額。','This file has not passed chart and data checks; prior balances will not be prefilled.','ឯកសារមិនទាន់ឆ្លងការពិនិត្យគណនី និងទិន្នន័យ; មិនបញ្ចូលសមតុល្យមុន។')}</p>`:''}`:''}</section>`}
function accWorkbookForm(c,kind='importtemplate'){if(!['importtemplate','importworkbook'].includes(kind))kind='importtemplate';accountingWorkbookImport=null;modal(kind==='importworkbook'?L('匯入 Journal 傳票','Import Journal vouchers','នាំចូលប័ណ្ណ Journal'):L('讀取公司科目範本','Read company chart template','អានគំរូគណនីក្រុមហ៊ុន'),`<form class="form" data-form="accounting" data-kind="${kind}" data-company="${esc(c)}" data-revision="${accS().revision}"><p>${esc(companyName(c))}</p><label>${L('選擇公司 .xlsx 工作簿','Select company .xlsx workbook','ជ្រើសសៀវភៅ .xlsx ក្រុមហ៊ុន')}<input type="file" data-acc-workbook-file accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></label><p class="help">${kind==='importtemplate'?L('這一步只匯入科目與報表分類；金額不會入帳。','This step imports account and report structure only; no amounts are posted.','ជំហាននេះនាំចូលតែគណនី និងរចនាសម្ព័ន្ធរបាយការណ៍។'):L('Journal 會按傳票號碼分組。整批核對通過後，建立草稿；仍需複核、核准與入帳。','Journal rows are grouped by voucher number. A valid batch creates drafts, followed by review, approval and posting.','ជួរ Journal ដាក់ក្រុមតាមលេខប័ណ្ណ។ ពិនិត្យរួចបង្កើតព្រាង ហើយពិនិត្យ អនុម័ត និងកត់ត្រា។')}</p><button type="button" data-action="acc-workbook-preview">${L('讀取並預覽','Read and preview','អាន និងមើលជាមុន')}</button><div data-acc-workbook-preview aria-live="polite"></div><label class="check"><input type="checkbox" name="confirmed" required>${L('已核對預覽，確認匯入這家公司','Preview checked; import into this company','បានពិនិត្យ បញ្ជាក់នាំចូលក្រុមហ៊ុននេះ')}</label>${accSubmit(kind==='importworkbook'?L('建立傳票草稿','Create voucher drafts','បង្កើតព្រាងប័ណ្ណ'):L('儲存科目範本','Save chart template','រក្សាគំរូគណនី'))}</form>`)}
async function accWorkbookPreview(){const epoch=workspaceAuthEpoch,f=$('#dialog form'),file=f.querySelector('[data-acc-workbook-file]').files[0];if(!file)throw new Error(L('請先選擇 .xlsx 檔案。','Choose an .xlsx file first.','ជ្រើសឯកសារ .xlsx ជាមុន។'));if(!window.KYDWorkbookReader)throw new Error(L('Excel 讀取工具未載入，請重新整理網頁。','Excel reader did not load. Refresh the page.','ឧបករណ៍អាន Excel មិនបានផ្ទុក។ សូមផ្ទុកទំព័រឡើងវិញ។'));const company=f.dataset.company,kind=f.dataset.kind,box=f.querySelector('[data-acc-workbook-preview]');box.textContent=L('正在讀取及核對…','Reading and validating…','កំពុងអាន និងពិនិត្យ…');accountingWorkbookImport=null;const data=await window.KYDWorkbookReader.read(file,{company});assertWorkspaceEpoch(epoch);if(f!==$('#dialog form')||f.querySelector('[data-acc-workbook-file]').files[0]!==file)return;let preview=null;const sourceErrors=kind==='importworkbook'?accWorkbookSourceMatch(data,company).errors:[],blocked=(data.errors||[]).length>0||sourceErrors.length>0;if(!blocked){if(kind==='importtemplate')preview=await api('accounting/previewtemplate',{company,template:data.template});else if(data.journals.length)preview=await api('accounting/previewworkbook',{company,journals:data.journals})}assertWorkspaceEpoch(epoch);if(f!==$('#dialog form')||f.querySelector('[data-acc-workbook-file]').files[0]!==file)return;const errors=[...(data.errors||[]),...sourceErrors,...(preview?.errors||[])];accountingWorkbookImport={company,kind,data,preview,revision:Number(f.dataset.revision),file,canSave:!!preview?.hash&&errors.length===0};box.innerHTML=`<p><strong>${esc(file.name)}</strong></p><p>${data.template.accounts.length} ${L('個科目','accounts','គណនី')} · ${data.journals.length} ${L('組傳票','voucher groups','ក្រុមប័ណ្ណ')} · ${Object.keys(data.openingValues||{}).length} ${L('筆前期餘額','prior balances','សមតុល្យមុន')}</p>${errors.length?`<ul class="acc-import-errors">${errors.map(x=>`<li>${esc([x.sheet,x.row,x.voucher].filter(Boolean).join(' · '))} ${esc(x.message)}</li>`).join('')}</ul>`:''}${data.warnings?.length?`<details open><summary>${L('讀取時需注意','Import notes','កំណត់សម្គាល់នាំចូល')}</summary><ul class="acc-import-errors">${data.warnings.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}${kind==='importworkbook'&&!data.journals.length?`<p class="acc-warning">${L('這份檔案沒有可匯入的 Journal 金額；不會建立空白或零元傳票。','No Journal amounts to import. No empty or zero-value vouchers will be created.','គ្មានទឹកប្រាក់ Journal សម្រាប់នាំចូល។ មិនបង្កើតប័ណ្ណទទេ ឬសូន្យ។')}</p>`:''}${accountingWorkbookImport.canSave?`<p class="badge green">${L('核對通過，可確認匯入','Validated; ready to import','ពិនិត្យរួច អាចនាំចូល')}</p>`:''}${preview?.vouchers?.length?`<ul class="acc-import-errors">${preview.vouchers.map(v=>`<li>${esc(v.key||v.voucher)} · ${esc(v.date)} · ${accAmount(v.total,accBook(company))} ${esc(v.currency||'')}</li>`).join('')}</ul>`:''}`}
const accCashFlowLabels={cash:['現金與約當現金','Cash and equivalents','សាច់ប្រាក់ និងសមមូល'],working_capital:['營運資金','Working capital','ទុនបង្វិល'],investing:['投資活動','Investing','វិនិយោគ'],financing:['籌資活動','Financing','ហិរញ្ញប្បទាន'],noncash:['非現金調整','Non-cash adjustment','កែសម្រួលមិនមែនសាច់ប្រាក់'],unclassified:['待分類','Unclassified','មិនមានប្រភេទ']};
function accJournalExtra(l={}){return `<details class="form-extra full"><summary>${L('對象、單位及單據資料（選填）','Party, unit and document details (optional)','ភាគី ឯកតា និងឯកសារ (ស្រេចចិត្ត)')}</summary><div class="form-extra-body">${[['counterparty',['對象／名稱','Party / name','ភាគី / ឈ្មោះ']],['unitNo',['單位編號','Unit no.','លេខឯកតា']],['invoiceNo',['發票／PN 號碼','Invoice / PN no.','លេខវិក្កយបត្រ / PN']],['reference',['參考號碼','Reference no.','លេខយោង']],['remarks',['備註','Remarks','សម្គាល់']],['originalDescription',['原版描述（內部）','Original description (internal)','សេចក្តីពណ៌នាដើម (ផ្ទៃក្នុង)']],['adjustmentNote',['調整說明','Adjustment note','សម្គាល់កែតម្រូវ']],['note',['補充說明','Additional note','កំណត់សម្គាល់បន្ថែម']]].map(([key,label])=>accInput(accText(label),'line-'+key,l[key]||'','text','maxlength="'+({counterparty:160,unitNo:100,invoiceNo:150,reference:150}[key]||1000)+'" data-acc-meta="'+key+'"')).join('')}</div></details>`}
function accJournalDetails(l){const labels={counterparty:L('對象','Party','ភាគី'),unitNo:L('單位','Unit','ឯកតា'),invoiceNo:L('發票／PN','Invoice / PN','វិក្កយបត្រ / PN'),reference:L('參考號碼','Reference','លេខយោង'),remarks:L('備註','Remarks','សម្គាល់'),originalDescription:L('原版描述','Original description','សេចក្តីពណ៌នាដើម'),adjustmentNote:L('調整說明','Adjustment note','សម្គាល់កែតម្រូវ'),note:L('補充說明','Additional note','កំណត់សម្គាល់បន្ថែម')};return Object.entries(labels).filter(([key])=>l[key]).map(([key,label])=>`<small>${esc(label)}：${esc(l[key])}</small>`).join('')}

function accReportGroupName(value){const labels={revenue:['收入','Revenue','ចំណូល'],cost:['營業成本','Cost of sales / services','ថ្លៃដើមលក់ / សេវា'],operating_expense:['營業費用','Operating expenses','ចំណាយប្រតិបត្តិការ'],finance_cost:['財務成本及稅費','Finance costs and taxes','ថ្លៃហិរញ្ញវត្ថុ និងពន្ធ'],current_assets:['流動資產','Current assets','ទ្រព្យសកម្មចរន្ត'],noncurrent_assets:['非流動資產','Non-current assets','ទ្រព្យសកម្មមិនចរន្ត'],non_current_assets:['非流動資產','Non-current assets','ទ្រព្យសកម្មមិនចរន្ត'],current_liabilities:['流動負債','Current liabilities','បំណុលចរន្ត'],noncurrent_liabilities:['非流動負債','Non-current liabilities','បំណុលមិនចរន្ត'],non_current_liabilities:['非流動負債','Non-current liabilities','បំណុលមិនចរន្ត'],equity:['權益','Equity','មូលធន']};return labels[value]?accText(labels[value]):value}
function accCashflowLinks(r){const cf=r.cashflow;return [['noncashTransactions',L('非現金投資／籌資傳票（另列）','Non-cash investing / financing vouchers','ប័ណ្ណវិនិយោគ / ហិរញ្ញប្បទានមិនមែនសាច់ប្រាក់')],['mixedTransactions',L('需拆分核對的現金及非現金傳票','Vouchers requiring cash / non-cash separation','ប័ណ្ណត្រូវបែងចែកសាច់ប្រាក់ / មិនមែនសាច់ប្រាក់')]].filter(([key])=>cf[key]?.length).map(([key,label])=>`<section class="card section-gap"><h2>${label}</h2>${cf[key].map(x=>`<p><a href="${href('finance',{company:r.company,tab:'journals',detail:x.entryId})}">${esc(x.number||x.entryId)} · ${esc(x.date)} · ${esc(x.description)} →</a></p>`).join('')}</section>`).join('')}
function accCashflowWarning(message){const labels={
'現金流量表為間接法工作草稿；非現金投資、融資、稅款及利息分類須由財務複核。':['現金流量表為間接法工作草稿；非現金投資、融資、稅款及利息分類須由財務複核。','Indirect-method working draft. Finance must review non-cash investing, financing, tax and interest classifications.','ព្រាងវិធីប្រយោល។ ហិរញ្ញវត្ថុត្រូវពិនិត្យប្រភេទវិនិយោគ ហិរញ្ញប្បទាន ពន្ធ និងការប្រាក់។'],
'尚未指定現金及銀行科目，現金期初期末無法確認。':['尚未指定現金及銀行科目，現金期初期末無法確認。','Cash and bank accounts are not classified; opening and closing cash cannot yet be confirmed.','មិនទាន់កំណត់គណនីសាច់ប្រាក់ និងធនាគារ; មិនអាចបញ្ជាក់សមតុល្យដើម និងចុង។'],
'仍有未分類科目變動，請補齊現金流量分類。':['仍有未分類科目變動，請補齊現金流量分類。','Some account movements are unclassified. Complete the cash flow mappings.','មានការប្រែប្រួលគណនីមិនទាន់ចាត់ថ្នាក់។ សូមបំពេញប្រភេទលំហូរសាច់ប្រាក់។'],
'計算淨變動與現金科目變動不一致，請完成差額調節。':['計算淨變動與現金科目變動不一致，請完成差額調節。','Calculated movement differs from the cash ledger movement. Reconcile the difference.','បម្រែបម្រួលគណនាខុសពីបញ្ជីសាច់ប្រាក់។ សូមផ្ទៀងផ្ទាត់ភាពខុសគ្នា។'],
'未涉及現金的投資或融資傳票已另列揭露，未計入現金收付。':['未涉及現金的投資或融資傳票已另列揭露，未計入現金收付。','Non-cash investing or financing vouchers are disclosed separately and excluded from cash receipts/payments.','ប័ណ្ណវិនិយោគ ឬហិរញ្ញប្បទានមិនមែនសាច់ប្រាក់បង្ហាញដោយឡែក និងមិនរាប់ជាសាច់ប្រាក់។'],
'存在同時含現金與多個對應科目的投資或融資傳票，現金與非現金部分須由財務拆分複核。':['存在同時含現金與多個對應科目的投資或融資傳票，現金與非現金部分須由財務拆分複核。','Some investing/financing vouchers mix cash with multiple counterpart accounts. Finance must review the cash and non-cash portions.','ប័ណ្ណខ្លះរួមសាច់ប្រាក់ និងគណនីច្រើន។ ហិរញ្ញវត្ថុត្រូវពិនិត្យ និងបែងចែកផ្នែកសាច់ប្រាក់ និងមិនមែនសាច់ប្រាក់។']};return labels[message]?accText(labels[message]):message}
